        vector<int> a(n);
        for (int i = 0; i < n; ++i) {
            cin >> a[i];          // 读入原排列 p
        }

        // 情况1：n < 3 无解
        if (n < 3) {
            cout << "NO\n";
            continue;
        }

        // 寻找最右侧下降点 idx，使得 a[idx] > a[idx+1]
        int idx = -1;
        for (int i = n - 2; i >= 0; --i) {
            if (a[i] > a[i + 1]) {
                idx = i;
                break;
            }
        }
        // 如果没有下降点，排列已全增，无解
        if (idx < 0) {
            cout << "NO\n";
            continue;
        }

        // 构造 q 并局部交换
        vector<int> b = a;
        if (idx <= n - 3) {
            // 交换 b[idx] 与 b[idx+2]
            swap(b[idx], b[idx + 2]);
        } else {
            // idx == n-2，交换 b[idx-1] 与 b[idx]
            swap(b[idx - 1], b[idx]);
        }

        // 输出结果
        cout << "YES\n";
        for (int i = 0; i < n; ++i) {
            cout << b[i] << (i + 1 < n ? ' ' : '\n');
        }
    }
    return 0;
}
